  // Fetch the satin bags
  const satinResp = await fetch('/v1/search-service/g/purses-accessories/view-all-handbags-and-wallets?fabric=satin&occasion=dress&product_type=handbags&id=cat100250002');
  const satinData = await satinResp.json().catch(() => null);

  return {
    goldCount: goldData?.totalNumRecs || goldData?.products?.length,
    goldProducts: goldData?.products?.map(p => ({
      name: p.name,
      minPrice: p.prices?.[0]?.minPrice,
      maxPrice: p.prices?.[0]?.maxPrice,
      colors: p.colors?.map(c => c.name),
      materials: p.materials
    })),
    satinCount: satinData?.totalNumRecs || satinData?.products?.length,
    satinProducts: satinData?.products?.map(p => ({
      name: p.name,
      minPrice: p.prices?.[0]?.minPrice,
      maxPrice: p.prices?.[0]?.maxPrice,
      colors: p.colors?.map(c => c.name)
    }))
  };
});
