// Let's set Min = 1, Max = 100 and click the customRangeFilter button
const result = await browserjs(tabId, () => {
  const panel = document.getElementById('filterslider-accordion-panel-8') || document.getElementById('filterpanel-accordion-panel-8');
  const minInput = panel?.querySelector('input[placeholder="Min"]');
  const maxInput = panel?.querySelector('input[placeholder="Max"]');
  const btn = panel?.querySelector('button[data-automation-id="customRangeFilter"]');

  if (minInput) {
    minInput.value = '1';
    minInput.dispatchEvent(new Event('input', { bubbles: true }));
    minInput.dispatchEvent(new Event('change', { bubbles: true }));
  }
  if (maxInput) {
    maxInput.value = '100';
    maxInput.dispatchEvent(new Event('input', { bubbles: true }));
    maxInput.dispatchEvent(new Event('change', { bubbles: true }));
  }
  btn?.click();
  return { submitted: !!btn };
});
